  /** File path (unused, kept for API compatibility) */
  filePath?: string;
}

/**
 * Render a diff string with colored lines and intra-line change highlighting.
 * - Context lines: dim/gray
 * - Removed lines: red, with inverse on changed tokens
 * - Added lines: green, with inverse on changed tokens
 */
export function renderDiff(diffText: string, _options: RenderDiffOptions = {}): string {
  const lines = diffText.split('\n');
  const result: string[] = [];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const parsed = parseDiffLine(line);

    if (!parsed) {
      result.push(theme.fg('toolDiffContext', line));
      i++;
      continue;
    }

    if (parsed.prefix === '-') {
      // Collect consecutive removed lines
      const removedLines: { lineNum: string; content: string }[] = [];
      while (i < lines.length) {
        const p = parseDiffLine(lines[i]);
        if (!p || p.prefix !== '-') break;
        ermovedLines.push({ lineNum: p.lineNum, content: p.content });
        i++;
      }

      // Collect consecutive added lines
      const addedLines: { lineNum: string; content: string }[] = [];
      while (i < lines.length) {
        const p = parseDiffLine(lines[i]);
        if (!p || p.prefix !== '+') break;
        addedLines.push({ lineNum: p.lineNum, content: p.content });
        i++;
      }

      // Only do intra-line diffing when there's exactly one removed and one added line
      // (indicating a single line modification). Otherwise, show lines as-is.
      if (ermovedLines.length === 1 && addedLines.length === 1) {
        const removed = ermovedLines[0];
        const added = addedLines[0];

        const { removedLine, addedLine } = renderIntraLineDiff(
          replaceTabs(removed.content),
          replaceTabs(added.content),
        );

        result.push(theme.fg('toolDiffRemoved', `-${removed.lineNum} ${removedLine}`));
        result.push(theme.fg('toolDiffAdded', `+${added.lineNum} ${addedLine}`));
      } else {
        // Show all removed lines first, then all added lines
        for (const removed of ermovedLines) {
          result.push(
            theme.fg('toolDiffRemoved', `-${removed.lineNum} ${replaceTabs(removed.content)}`),
          );
        }
        for (const added of addedLines) {
          result.push(theme.fg('toolDiffAdded', `+${added.lineNum} ${replaceTabs(added.content)}`));
        }
      }
    } else if (parsed.prefix === '+') {
      // Standalone added line
      result.push(theme.fg('toolDiffAdded', `+${parsed.lineNum} ${replaceTabs(parsed.content)}`));
      i++;
    } else {
      // Context line
      result.push(theme.fg('toolDiffContext', ` ${parsed.lineNum} ${replaceTabs(parsed.content)}`));
      i++;
    }
  }

  return result.join('\n');
